-- Milestone 2 — clinic reference data: therapists, services, rooms, tariffs.
--
-- The section above the "HAND-WRITTEN" banner is generated by Prisma.
-- Everything below it is hand-written, because Prisma cannot express CHECK
-- constraints, exclusion constraints, functions or triggers. Each hand-written
-- object is named, and an integration test asserts every name exists in the
-- PostgreSQL catalogue, so a future edit cannot quietly drop one.
--
-- This migration is create-only: it adds two enums and seven tables and alters
-- nothing Milestone 1 created. Applying it to a database holding real staff
-- accounts changes none of them.
--
-- On timestamps: as in Milestone 1, `CURRENT_TIMESTAMP` is PostgreSQL's exact
-- synonym for `transaction_timestamp()` — the transaction start time, not the
-- wall clock at statement execution. Every row written in one transaction
-- shares an instant, so a state change and its audit row are provably
-- simultaneous. The spelling is left as Prisma generates it so schema-drift
-- detection cannot produce a false positive on a synonym.

-- CreateEnum
CREATE TYPE "catalog_status" AS ENUM ('ACTIVE', 'INACTIVE');

-- CreateEnum
CREATE TYPE "tariff_price_mode" AS ENUM ('PAID', 'FREE');

-- CreateTable
CREATE TABLE "therapist" (
    "id" UUID NOT NULL,
    "full_name" TEXT NOT NULL,
    "specialty" TEXT NOT NULL,
    "status" "catalog_status" NOT NULL DEFAULT 'ACTIVE',
    "deactivated_at" TIMESTAMPTZ,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "created_by_user_id" UUID NOT NULL,

    CONSTRAINT "therapist_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "service" (
    "id" UUID NOT NULL,
    "name" TEXT NOT NULL,
    "public_description" TEXT,
    "is_public" BOOLEAN NOT NULL DEFAULT false,
    "status" "catalog_status" NOT NULL DEFAULT 'ACTIVE',
    "deactivated_at" TIMESTAMPTZ,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "created_by_user_id" UUID NOT NULL,

    CONSTRAINT "service_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "service_duration" (
    "id" UUID NOT NULL,
    "service_id" UUID NOT NULL,
    "duration_minutes" INTEGER NOT NULL,

    CONSTRAINT "service_duration_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "room" (
    "id" UUID NOT NULL,
    "name" TEXT NOT NULL,
    "status" "catalog_status" NOT NULL DEFAULT 'ACTIVE',
    "deactivated_at" TIMESTAMPTZ,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "created_by_user_id" UUID NOT NULL,

    CONSTRAINT "room_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "therapist_service" (
    "therapist_id" UUID NOT NULL,
    "service_id" UUID NOT NULL,

    CONSTRAINT "therapist_service_pkey" PRIMARY KEY ("therapist_id","service_id")
);

-- CreateTable
CREATE TABLE "room_service" (
    "room_id" UUID NOT NULL,
    "service_id" UUID NOT NULL,

    CONSTRAINT "room_service_pkey" PRIMARY KEY ("room_id","service_id")
);

-- CreateTable
CREATE TABLE "tariff" (
    "id" UUID NOT NULL,
    "service_id" UUID NOT NULL,
    "duration_minutes" INTEGER NOT NULL,
    "therapist_id" UUID,
    "price_mode" "tariff_price_mode" NOT NULL,
    "price_toman" BIGINT NOT NULL,
    "free_reason" TEXT,
    "effective_start" DATE NOT NULL,
    "effective_end" DATE,
    "voided_at" TIMESTAMPTZ,
    "void_reason" TEXT,
    "supersedes_tariff_id" UUID,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "created_by_user_id" UUID NOT NULL,

    CONSTRAINT "tariff_pkey" PRIMARY KEY ("id")
);

