-- ===========================================================================
-- HAND-WRITTEN — everything below this line is reviewed by a human, not
-- generated. Prisma cannot express CHECK constraints, composite foreign keys,
-- exclusion constraints, functions or triggers.
--
-- NOTE ON CREATOR FOREIGN KEYS: all four catalog tables carry
-- `created_by_user_id` as NOT NULL REFERENCES app_user. There is deliberately
-- no anonymous or system path that creates clinic reference data — it is
-- entered by a signed-in manager, and the row names them. Those four keys are
-- generated above; this note exists so their NOT NULL is understood as a
-- decision rather than a default.
-- ===========================================================================

-- Required by the tariff exclusion constraints below: GiST indexes cannot
-- compare uuid, integer or enum values with `=` without it.
CREATE EXTENSION IF NOT EXISTS btree_gist;

-- --- Canonical outer whitespace ---------------------------------------------
--
-- Every identifying text column is stored already trimmed, and the database
-- says so. Without `= btrim(...)`, "اتاق ۱" and " اتاق ۱ " are two different
-- values to a UNIQUE index and one indistinguishable value to a human reading
-- a list, which is how a duplicate room ends up in a booking screen.
--
-- The shared Zod contracts trim before validating, so this constraint is a
-- second line rather than the first, and it holds even for a write that never
-- passed through them.
--
-- Outer whitespace only. There is deliberately no Persian yeh/kaf folding, no
-- internal-whitespace collapsing and no fuzzy matching: each of those silently
-- rewrites what a user typed, and near-duplicate detection is a separate
-- feature that has not been approved.

-- --- therapist CHECK constraints ---------------------------------------------

ALTER TABLE "therapist" ADD CONSTRAINT "therapist_full_name_chk"
    CHECK (
        "full_name" = btrim("full_name")
        AND btrim("full_name") <> ''
        AND length("full_name") <= 120
    );

ALTER TABLE "therapist" ADD CONSTRAINT "therapist_specialty_chk"
    CHECK (
        "specialty" = btrim("specialty")
        AND btrim("specialty") <> ''
        AND length("specialty") <= 120
    );

-- An inactive therapist always records when they were deactivated, and an
-- active one never claims to have been. Mirrors app_user_disabled_consistency_chk.
ALTER TABLE "therapist" ADD CONSTRAINT "therapist_deactivated_consistency_chk"
    CHECK (("status" = 'INACTIVE') = ("deactivated_at" IS NOT NULL));

-- --- service CHECK constraints -----------------------------------------------

ALTER TABLE "service" ADD CONSTRAINT "service_name_chk"
    CHECK (
        "name" = btrim("name")
        AND btrim("name") <> ''
        AND length("name") <= 120
    );

-- Bounded, and trimmed when present. A public description may be absent, but it
-- may not be a run of spaces pretending to be prose.
ALTER TABLE "service" ADD CONSTRAINT "service_public_description_chk"
    CHECK (
        "public_description" IS NULL
        OR (
            "public_description" = btrim("public_description")
            AND btrim("public_description") <> ''
            AND length("public_description") <= 2000
        )
    );

ALTER TABLE "service" ADD CONSTRAINT "service_deactivated_consistency_chk"
    CHECK (("status" = 'INACTIVE') = ("deactivated_at" IS NOT NULL));

-- --- room CHECK constraints --------------------------------------------------

ALTER TABLE "room" ADD CONSTRAINT "room_name_chk"
    CHECK (
        "name" = btrim("name")
        AND btrim("name") <> ''
        AND length("name") <= 120
    );

ALTER TABLE "room" ADD CONSTRAINT "room_deactivated_consistency_chk"
    CHECK (("status" = 'INACTIVE') = ("deactivated_at" IS NOT NULL));

-- --- service_duration CHECK constraints ---------------------------------------

-- Eight hours is not a plausible session length; it is the point past which a
-- typed value is a mistake rather than a long appointment.
ALTER TABLE "service_duration" ADD CONSTRAINT "service_duration_positive_chk"
    CHECK ("duration_minutes" > 0 AND "duration_minutes" <= 480);

-- --- tariff CHECK constraints ------------------------------------------------

-- General sanity bound, applicable in both price modes. 1,000,000,000 toman is
-- a fat-finger guard, not a modelled ceiling: it exists so a mistyped run of
-- digits is refused at entry rather than discovered in a report.
ALTER TABLE "tariff" ADD CONSTRAINT "tariff_price_bounds_chk"
    CHECK ("price_toman" >= 0 AND "price_toman" <= 1000000000);

-- The price mode is explicit and is never inferred from `price_toman = 0`.
--
-- The clinic runs genuinely free programmes — complimentary screening,
-- introductory consultations — and that is a different fact from an ordinarily
-- paid service discounted to nothing for one family. The first is a FREE
-- tariff, created here with a stated reason; the second stays a PAID tariff and
-- is handled by the later discount model, which preserves the original price.
--
-- PAID therefore requires a real amount and no free-programme reason; FREE
-- requires exactly zero and an explanation. Neither shape can be reached by
-- accident from the other.
ALTER TABLE "tariff" ADD CONSTRAINT "tariff_price_mode_chk"
    CHECK (
        ("price_mode" = 'PAID' AND "price_toman" > 0 AND "free_reason" IS NULL)
        OR
        ("price_mode" = 'FREE' AND "price_toman" = 0 AND "free_reason" IS NOT NULL)
    );

ALTER TABLE "tariff" ADD CONSTRAINT "tariff_free_reason_chk"
    CHECK (
        "free_reason" IS NULL
        OR (
            "free_reason" = btrim("free_reason")
            AND btrim("free_reason") <> ''
            AND length("free_reason") <= 500
        )
    );

-- A NULL end is open-ended, which is the common case for a current price.
ALTER TABLE "tariff" ADD CONSTRAINT "tariff_effective_range_chk"
    CHECK ("effective_end" IS NULL OR "effective_end" >= "effective_start");

-- A voided tariff always records why, and a live one never claims to have been
-- voided.
ALTER TABLE "tariff" ADD CONSTRAINT "tariff_void_consistency_chk"
    CHECK (("voided_at" IS NULL) = ("void_reason" IS NULL));

ALTER TABLE "tariff" ADD CONSTRAINT "tariff_void_reason_chk"
    CHECK (
        "void_reason" IS NULL
        OR (
            "void_reason" = btrim("void_reason")
            AND btrim("void_reason") <> ''
            AND length("void_reason") <= 500
        )
    );

-- NOTE ON THE COMPOSITE FOREIGN KEY: "a tariff may only price a duration its
-- service actually offers" is enforced by
-- `tariff_service_id_duration_minutes_fkey`, generated above from a declared
-- Prisma relation rather than hand-written here.
--
-- That was worth confirming rather than assuming: `service_id` participates in
-- two relations at once — the single-column one to `service` and this composite
-- one to `service_duration` — and Prisma accepts it. Keeping the key in the
-- datamodel matters because `prisma migrate diff` DOES see foreign keys, unlike
-- CHECK constraints and triggers, so a hand-written one reads as permanent
-- schema drift and fails CI on every run.
--
-- Its ON DELETE RESTRICT is the same rule read from the other end: a duration
-- cannot be withdrawn while any tariff still prices it, including a voided one,
-- because a voided tariff is history and history keeps its references.

-- --- tariff overlap prevention -----------------------------------------------
--
-- Two constraints rather than one, because `=` in an exclusion constraint does
-- not treat NULL as equal to NULL. A single constraint covering both cases
-- would silently permit any number of overlapping general tariffs, which is
-- precisely the case that decides a price when no therapist-specific tariff
-- applies.
--
-- Both are partial on `voided_at IS NULL`: a voided row is history and may
-- overlap anything. Enforcing this in the database rather than by reading
-- before writing is what makes it hold under concurrency — two simultaneous
-- inserts cannot both pass, whatever the application checked first.

ALTER TABLE "tariff" ADD CONSTRAINT "tariff_no_overlap_therapist_excl"
    EXCLUDE USING GIST (
        "service_id" WITH =,
        "duration_minutes" WITH =,
        "therapist_id" WITH =,
        daterange("effective_start", "effective_end", '[]') WITH &&
    ) WHERE ("voided_at" IS NULL AND "therapist_id" IS NOT NULL);

ALTER TABLE "tariff" ADD CONSTRAINT "tariff_no_overlap_general_excl"
    EXCLUDE USING GIST (
        "service_id" WITH =,
        "duration_minutes" WITH =,
        daterange("effective_start", "effective_end", '[]') WITH &&
    ) WHERE ("voided_at" IS NULL AND "therapist_id" IS NULL);

-- --- no-delete enforcement (reuses the Milestone 1 shared function) ----------
--
-- Catalog rows are permanent historical records: a tariff will be named by a
-- session charge, and a therapist, service and room by an appointment.
-- Deactivation is `status = INACTIVE`; voiding is `voided_at`. The TRUNCATE
-- triggers are not optional — TRUNCATE bypasses row-level triggers entirely.

CREATE TRIGGER "therapist_no_delete"
    BEFORE DELETE ON "therapist"
    FOR EACH ROW EXECUTE FUNCTION "raise_append_only_violation"();

CREATE TRIGGER "therapist_no_truncate"
    BEFORE TRUNCATE ON "therapist"
    FOR EACH STATEMENT EXECUTE FUNCTION "raise_append_only_violation"();

CREATE TRIGGER "service_no_delete"
    BEFORE DELETE ON "service"
    FOR EACH ROW EXECUTE FUNCTION "raise_append_only_violation"();

CREATE TRIGGER "service_no_truncate"
    BEFORE TRUNCATE ON "service"
    FOR EACH STATEMENT EXECUTE FUNCTION "raise_append_only_violation"();

CREATE TRIGGER "room_no_delete"
    BEFORE DELETE ON "room"
    FOR EACH ROW EXECUTE FUNCTION "raise_append_only_violation"();

CREATE TRIGGER "room_no_truncate"
    BEFORE TRUNCATE ON "room"
    FOR EACH STATEMENT EXECUTE FUNCTION "raise_append_only_violation"();

CREATE TRIGGER "tariff_no_delete"
    BEFORE DELETE ON "tariff"
    FOR EACH ROW EXECUTE FUNCTION "raise_append_only_violation"();

CREATE TRIGGER "tariff_no_truncate"
    BEFORE TRUNCATE ON "tariff"
    FOR EACH STATEMENT EXECUTE FUNCTION "raise_append_only_violation"();

-- service_duration, therapist_service and room_service deliberately carry no
-- delete trigger: they are current configuration, not historical fact. A
-- service's durations may be revised and a therapist's supported services
-- replaced, with the change recorded in audit_log. service_duration is still
-- protected where it matters by tariff_duration_fkey above.

-- --- tariff immutability ------------------------------------------------------
--
-- A tariff is written once. Correcting a price voids the row and inserts a
-- replacement, so the price that applied on a past date stays readable exactly
-- as it was applied, and "what did this cost in Mordad?" has an answer that
-- later edits cannot change.
--
-- Enforced here rather than only in the service layer because that is the
-- difference between an invariant and a convention: a future endpoint, a
-- migration script or a debugging session at a psql prompt cannot rewrite
-- financial history by accident.
--
-- Exactly one transition is permitted: active to voided. Everything else —
-- changing what is priced, changing the price, unvoiding, or rewriting a void
-- reason after the fact — raises restrict_violation (SQLSTATE 23001), the same
-- stable code raise_append_only_violation uses, so tests assert one code for
-- every "the database refuses to rewrite this" failure.
CREATE OR REPLACE FUNCTION "enforce_tariff_immutability"() RETURNS trigger
    LANGUAGE plpgsql AS $fn$
BEGIN
    -- What the tariff is, and what it charges. None of it changes, ever —
    -- voided or not. price_mode and free_reason are as defining as the amount:
    -- a paid tariff quietly becoming a free one would rewrite what the clinic
    -- charged, which is the whole class of edit this trigger exists to refuse.
    IF NEW."id"                   IS DISTINCT FROM OLD."id"
        OR NEW."service_id"           IS DISTINCT FROM OLD."service_id"
        OR NEW."duration_minutes"     IS DISTINCT FROM OLD."duration_minutes"
        OR NEW."therapist_id"         IS DISTINCT FROM OLD."therapist_id"
        OR NEW."price_mode"           IS DISTINCT FROM OLD."price_mode"
        OR NEW."price_toman"          IS DISTINCT FROM OLD."price_toman"
        OR NEW."free_reason"          IS DISTINCT FROM OLD."free_reason"
        OR NEW."effective_start"      IS DISTINCT FROM OLD."effective_start"
        OR NEW."effective_end"        IS DISTINCT FROM OLD."effective_end"
        OR NEW."supersedes_tariff_id" IS DISTINCT FROM OLD."supersedes_tariff_id"
        OR NEW."created_at"           IS DISTINCT FROM OLD."created_at"
        OR NEW."created_by_user_id"   IS DISTINCT FROM OLD."created_by_user_id"
    THEN
        RAISE EXCEPTION
            'tariff % is immutable; only a single void transition is permitted', OLD."id"
            USING ERRCODE = 'restrict_violation';
    END IF;

    -- Voiding is a one-way door. Once voided, the void itself is history too:
    -- no unvoiding, and no revising the stated reason afterwards.
    IF OLD."voided_at" IS NOT NULL
        AND (
            NEW."voided_at"   IS DISTINCT FROM OLD."voided_at"
            OR NEW."void_reason" IS DISTINCT FROM OLD."void_reason"
        )
    THEN
        RAISE EXCEPTION
            'tariff % is already voided; voided_at and void_reason cannot change again', OLD."id"
            USING ERRCODE = 'restrict_violation';
    END IF;

    RETURN NEW;
END;
$fn$;

CREATE TRIGGER "tariff_enforce_immutability"
    BEFORE UPDATE ON "tariff"
    FOR EACH ROW EXECUTE FUNCTION "enforce_tariff_immutability"();

-- NOTE ON COMPLETENESS: as in Milestone 1, a table owner can still run
-- `ALTER TABLE ... DISABLE TRIGGER`. Closing that gap needs a runtime database
-- role that does not own these tables. That remains a production hardening
-- item, unchanged by this milestone.
